import sys
from collections import deque, defaultdict

MOD = 1000000007

def main():
    input = sys.stdin.read().strip().split()
    n = int(input[0])
    k = int(input[1])
    values = list(map(int, input[2:]))

    a = sum(1 for v in values if v == 50)
    b = sum(1 for v in values if v != 50)

    choose = [[0]*100 for _ in range(100)]
    fill_choose(choose)

    start_mask = 1000000 + 100 * a + b
    q = deque()
    ways = dict()

    q.append(start_mask)
    ways[start_mask] = (0, 1)  # (distance, ways)

    while q:
        mask = q.popleft()
        bfs(mask, a, b, choose, q, ways, k)

    if 0 in ways:
        print(ways[0][0])
        print(ways[0][1])
    else:
        print(-1)
        print(0)

def bfs(mask, a, b, choose, q, ways, k):
    boat = mask // 1000000
    nA = (mask % 1000000) // 100
    nB = mask % 100

    if boat > 0:
        for i in range(nA, -1, -1):
            if 50 * (nA - i) > k:
                continue
            for j in range(nB, -1, -1):
                if 50 * (nA - i) + 100 * (nB - j) > k:
                    continue
                if i != nA or j != nB:
                    resolve(i, j, boat, mask, choose[nA][i] * choose[nB][j] % MOD, a, b, choose, q, ways, k)
    else:
        for i in range(nA, a + 1):
            if 50 * (i - nA) > k:
                continue
            for j in range(nB, b + 1):
                if 50 * (i - nA) + 100 * (j - nB) > k:
                    continue
                if i != nA or j != nB:
                    resolve(i, j, boat, mask, choose[a - nA][i - nA] * choose[b - nB][j - nB] % MOD, a, b, choose, q, ways, k)

def resolve(i, j, boat, mask, edgeWays, a, b, choose, q, ways, k):
    new_mask = 1000000 * (1 - boat) + i * 100 + j
    newD, newW = ways.get(new_mask, (float('inf'), 0))
    oldD, oldW = ways.get(mask, (float('inf'), 0))
    newD = oldD + 1
    if new_mask not in ways or ways[new_mask][0] > newD:
        ways[new_mask] = (newD, 0)
        q.append(new_mask)
    if ways[new_mask][0] == newD:
        ways[new_mask] = (newD, (ways[new_mask][1] + oldW * edgeWays) % MOD)

def fill_choose(choose):
    for i in range(100):
        choose[i][0] = 1
    for i in range(1, 100):
        for j in range(1, i + 1):
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

if __name__ == "__main__":
    main()

